const input = $input.first().json;

// Support both Form submission and Manual / Scheduled trigger inputs
const rawCompany = input["Company Name or Website URL"] || input.companyName || input.company || "Supabase";
const rawProduct = input["Specific Product Name (Optional)"] || input.productName || input.product || "";
const rawIndustry = input["Industry or Category (Optional)"] || input.industry || "Cloud Databases & Developer Platforms";
const recipientEmail = input["Recipient Email"] || input.recipientEmail || "mayur.narkar@svims.com";

const isProductSpecific = Boolean(rawProduct && rawProduct.trim().length > 0);
const targetScope = isProductSpecific ? "PRODUCT_SPECIFIC_AUDIT" : "ENTERPRISE_HOLISTIC_AUDIT";
const targetTitle = isProductSpecific ? `${rawCompany.trim()} (${rawProduct.trim()})` : rawCompany.trim();

let domain = rawCompany.trim();
if (!domain.startsWith('http://') && !domain.startsWith('https://')) {
  if (domain.includes('.')) {
    domain = 'https://' + domain;
  } else {
    domain = `https://www.${domain.toLowerCase().replace(/[^a-z0-9]/g, '')}.com`;
  }
}

const query = `${rawCompany.trim()} ${rawProduct ? rawProduct.trim() : ''} launch OR funding OR competitor OR pricing OR acquisition`;
const newsSearchUrl = `https://news.google.com/rss/search?q=${encodeURIComponent(query)}&hl=en-US&gl=US&ceid=US:en`;
const hnSearchUrl = `https://hn.algolia.com/api/v1/search?query=${encodeURIComponent(rawCompany.trim() + ' alternative OR launch')}&tags=story&hitsPerPage=6`;

return {
  json: {
    companyName: rawCompany.trim(),
    productName: isProductSpecific ? rawProduct.trim() : null,
    industry: rawIndustry.trim(),
    isProductSpecific,
    targetScope,
    targetTitle,
    resolvedDomain: domain,
    newsSearchUrl,
    hnSearchUrl,
    recipientEmail
  }
};

const scope = $('Resolve Target & Horizon Scope').first().json;
const newsRaw = $('Fetch Live Market News').first().json;
const hnRaw = $('Fetch Community Signals & Disruptors').first().json;

let newsItems = [];
try {
  const xml = typeof newsRaw === 'string' ? newsRaw : (newsRaw.data || JSON.stringify(newsRaw));
  const itemRegex = /<item>([\s\S]*?)<\/item>/gi;
  let match;
  while ((match = itemRegex.exec(xml)) !== null && newsItems.length < 6) {
    const itemContent = match[1];
    const titleMatch = /<title>([\s\S]*?)<\/title>/i.exec(itemContent);
    const pubDateMatch = /<pubDate>([\s\S]*?)<\/pubDate>/i.exec(itemContent);
    const sourceMatch = /<source[^>]*>([\s\S]*?)<\/source>/i.exec(itemContent);
    if (titleMatch) {
      const cleanTitle = titleMatch[1].replace(/<!\[CDATA\[(.*?)\]\]>/gi, '$1').replace(/<[^>]+>/g, '').trim();
      if (!cleanTitle.includes('Google News') && cleanTitle.length > 10) {
        newsItems.push({
          title: cleanTitle,
          pubDate: pubDateMatch ? pubDateMatch[1].trim() : 'Recent',
          source: sourceMatch ? sourceMatch[1].trim() : 'Industry Press'
        });
      }
    }
  }
} catch (e) {}

let hnItems = [];
try {
  const hits = hnRaw?.hits || [];
  for (const h of hits.slice(0, 5)) {
    if (h.title) {
      hnItems.push({
        title: h.title,
        points: h.points || 0,
        comments: h.num_comments || 0,
        date: h.created_at ? h.created_at.slice(0, 10) : 'Recent'
      });
    }
  }
} catch (e) {}

const currentDateStr = new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });

let liveTelemetryText = `CURRENT INTELLIGENCE AUDIT DATE: ${currentDateStr}\n\n`;
if (newsItems.length > 0) {
  liveTelemetryText += "VERIFIED LIVE BREAKING NEWS & FINANCIAL TELEMETRY:\n";
  newsItems.forEach(n => {
    liveTelemetryText += `* [${n.pubDate}] (${n.source}) ${n.title}\n`;
  });
  liveTelemetryText += "\n";
}
if (hnItems.length > 0) {
  liveTelemetryText += "COMMUNITY DISRUPTOR & SENTIMENT SIGNALS:\n";
  hnItems.forEach(h => {
    liveTelemetryText += `* [${h.date}] "${h.title}" (${h.points} upvotes, ${h.comments} comments)\n`;
  });
}

const prompt = `You are a Senior Partner at McKinsey & Company, Chief Strategy Officer, and Gartner Research Director.
Conduct an institutional-grade, rigorous COMPETITIVE & MARKET INTELLIGENCE AUDIT on:

TARGET COMPANY / ENTITY:
- Company Name: ${scope.companyName}
- Domain: ${scope.resolvedDomain}
- Industry Space: ${scope.industry}
- Audit Scope: ${scope.targetScope}
${scope.isProductSpecific ? `- Specific Product Line Focus: "${scope.productName}"` : '- Holistic Umbrella Entity'}

${liveTelemetryText}

CRITICAL RESEARCH GUIDELINES:
1. MAXIMUM FACTS & HARD NUMBERS: Whenever applicable, provide exact dollar figures, valuations, funding amounts, market size (TAM & CAGR), specific pricing tiers ($/mo, $/MAU, overages, seat pricing), latency metrics (ms), and scale indicators.
2. Ground your analysis in the REAL-TIME BREAKING TELEMETRY provided above. If acquisitions, funding rounds, or pricing controversies broke recently, incorporate them directly into your findings.
3. Categorize competitors systematically across the Gartner Magic Quadrant (Leaders, Visionary Challengers, Niche Specialists).
4. Provide a 4-pillar Feature Parity Matrix with quantitative benchmarks, Churn Driver Index, Blue Ocean Whitespaces with addressable dollar potentials, Preemptive 30/60/90 Day Roadmap, and The War Room Sales Kill-Sheet.

Return ONLY a pure JSON object conforming strictly to the responseSchema.`;

return {
  json: {
    ...scope,
    newsItems,
    hnItems,
    currentDateStr,
    liveTelemetryText,
    prompt
  }
};

