const resp = $input.first().json;
const meta = $('Resolve Target & Horizon Scope').first().json;

function safeParseJson(raw) {
  if (!raw || typeof raw !== 'string') return null;
  let text = raw.trim();
  const fence = String.fromCharCode(96).repeat(3);
  if (text.startsWith(fence + 'json')) text = text.slice(7);
  else if (text.startsWith(fence)) text = text.slice(3);
  if (text.endsWith(fence)) text = text.slice(0, -3);
  text = text.trim();
  try { return JSON.parse(text); } catch (e) {}
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start !== -1 && end > start) {
    try { return JSON.parse(text.substring(start, end + 1)); } catch (e2) {}
  }
  throw new Error("Unable to parse JSON from AI response: " + text.slice(0, 200));
}

let intel = null;
if (resp.candidates && resp.candidates.length > 0) {
  const parts = resp.candidates[0].content?.parts || [];
  const rawText = parts.map(p => p.text || '').join('').trim();
  intel = safeParseJson(rawText);
} else if (resp.error) {
  throw new Error("Gemini API Error: " + (resp.error.message || JSON.stringify(resp.error)));
} else {
  throw new Error("No candidates received from Gemini API");
}

const timestamp = new Date().toISOString();
const currentDateStr = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
const formUrl = "http://localhost:5678/form/market-radar-v2-form";

// 1. Mobile-friendly Breaking News Ticker
const telemetryHtml = (intel.breaking_market_telemetry || []).map(t => `
